import { isUndefined } from '@nestjs/common/utils/shared.utils.js';
export class UndefinedTypeError extends Error {
    constructor(name, key, index) {
        super(`Undefined type error. Make sure you are providing an explicit type for the "${key}" ${isUndefined(index) ? '' : `(parameter at index [${index}]) `}of the "${name}" class.`);
    }
}
